-- Synthetic regression: a declared FederalLaw may have an unknown ActualID.
-- Omission is not a verified identity and must NEVER earn automatic renewal.
-- Roll back this entire fixture so all original312 scenarios run unchanged.
SAVEPOINT unsupported_federal_law;
SET ROLE postgres;
SELECT lab.keep('unknown126_before_admission',rtn_private.npa_admission((lab.ctx('fresh_release')->>'release_id')::uuid,clock_timestamp()));
SELECT lab.keep('unknown126_before_key',(SELECT to_jsonb(k)FROM rtn_private.key_sets k WHERE k.id=(lab.ctx('fresh_review')->>'key_set_id')::uuid));
SELECT lab.keep('unknown126_before_source',(SELECT to_jsonb(s)FROM rtn_private.sources s WHERE s.id=(lab.ctx('source')->>'source_id')::uuid));
SELECT lab.keep('unknown126_identity','{"country":"RU","kind":"FederalLaw","date":"2026-05-02","number":"126-FZ","title":"Synthetic law with unknown ActualID"}');
SELECT lab.check('250 omitted126 docid stays unsupported',NOT rtn_private.npa_supported(lab.ctx('unknown126_identity')));
SELECT lab.check('250 explicitnull docid never supported',NOT rtn_private.npa_supported(lab.ctx('unknown126_identity')||'{"docid":null}'));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000999',false);
SELECT lab.keep('unknown126_basis',lab.ctx('basis')||jsonb_build_array(lab.ctx('unknown126_identity')));
SELECT lab.keep('unknown126_configuration',public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,lab.ctx('unknown126_basis'),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic known116 plus honestly unknown126','86000000-0000-4000-8000-000000000126'));
SELECT lab.check('250 genuine admin can declare missingActualID without fakeOther',lab.ctx('unknown126_configuration')->'supported_count'='1'::jsonb AND lab.ctx('unknown126_configuration')->'unsupported_count'='1'::jsonb AND lab.ctx('unknown126_configuration')->'basis'->1->>'kind'='FederalLaw'AND NOT(lab.ctx('unknown126_configuration')->'basis'->1?'docid'));
SELECT lab.keep('unknown126_replay',public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,lab.ctx('unknown126_basis'),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic known116 plus honestly unknown126','86000000-0000-4000-8000-000000000126'));
SELECT lab.check('250 unknownActualID configuration replay remains exact',lab.ctx('unknown126_replay')->'configuration_id'=lab.ctx('unknown126_configuration')->'configuration_id'AND lab.ctx('unknown126_replay')->'replayed'='true'::jsonb);
SELECT lab.keep('unknown126_queue',public.request_rtn_npa_editorial_check((lab.ctx('bank_id')#>>'{}')::uuid));
SET ROLE service_role;
SELECT set_config('request.jwt.claim.role','service_role',false);
SELECT lab.keep('unknown126_claim',public.claim_rtn_npa_check((lab.ctx('unknown126_queue')->>'run_id')::uuid));
SELECT lab.check('250 claim partitions omitted126 from supported116',jsonb_array_length(lab.ctx('unknown126_claim')->'basis')=1 AND jsonb_array_length(lab.ctx('unknown126_claim')->'unsupported_basis')=1 AND lab.ctx('unknown126_claim')->'all_declared_basis_count'='2'::jsonb AND lab.ctx('unknown126_claim')->'basis'->0->'docid'='38355'::jsonb);
SELECT lab.check('250 unsupported claim keeps honest126 identity',lab.ctx('unknown126_claim')->'unsupported_basis'->0->>'kind'='FederalLaw'AND lab.ctx('unknown126_claim')->'unsupported_basis'->0->>'number'='126-FZ'AND lab.ctx('unknown126_claim')->'unsupported_basis'->0->>'date'='2026-05-02'AND NOT(lab.ctx('unknown126_claim')->'unsupported_basis'->0?'docid'));
SELECT lab.keep('unknown126_result',lab.npa_result((lab.ctx('unknown126_claim')->>'run_id')::uuid)||'{"status":"partial_coverage","error_code":"UNSUPPORTED_DECLARED_BASIS"}');
SET ROLE postgres;
SELECT lab.keep('unknown126_proof',(SELECT rtn_private.npa_proof(lab.ctx('unknown126_result'),r,clock_timestamp())FROM rtn_private.npa_check_runs r WHERE r.id=(lab.ctx('unknown126_claim')->>'run_id')::uuid));
SELECT lab.check('250 known116 cannot falsely prove missing126',lab.ctx('unknown126_proof')->'full'='false'::jsonb AND lab.ctx('unknown126_proof')->'reason_codes'?'partial_declared_coverage');
SELECT lab.check('250 verified question and known116 facts remain distinct from allbasis proof',jsonb_array_length(lab.ctx('unknown126_proof')->'observations')=2);
SET ROLE service_role;
SELECT set_config('request.jwt.claim.role','service_role',false);
SELECT lab.keep('unknown126_complete',public.complete_rtn_npa_check((lab.ctx('unknown126_claim')->>'run_id')::uuid,(lab.ctx('unknown126_claim')->>'lease_token')::uuid,lab.ctx('unknown126_result')));
SELECT lab.check('250 partial126 receipt never creates renewal',lab.ctx('unknown126_complete')->>'outcome'='partial_coverage'AND lab.ctx('unknown126_complete')->'valid_until_exclusive'='null'::jsonb);
SET ROLE postgres;
SELECT lab.keep('unknown126_after_admission',rtn_private.npa_admission((lab.ctx('fresh_release')->>'release_id')::uuid,clock_timestamp()));
SELECT lab.check('250 unknown126 preserves exact remaining manualwindow',lab.ctx('unknown126_after_admission')->>'admission_basis'='manual_review'AND lab.ctx('unknown126_after_admission')->'allowed'='true'::jsonb AND lab.ctx('unknown126_after_admission')->'normative_cutoff_at'=lab.ctx('unknown126_before_admission')->'normative_cutoff_at');
SELECT lab.check('250 unknown126 cannot extend past originalmanualexpiry',NOT(rtn_private.npa_admission((lab.ctx('fresh_release')->>'release_id')::uuid,(lab.ctx('unknown126_before_admission')->>'normative_cutoff_at')::timestamptz+interval'1 second')->>'allowed')::boolean);
SELECT lab.check('250 unsupported126 never writes approvedmanifest orvalidreceipt',NOT EXISTS(SELECT 1 FROM rtn_private.npa_manifests)AND NOT EXISTS(SELECT 1 FROM rtn_private.npa_receipts WHERE run_id=(lab.ctx('unknown126_claim')->>'run_id')::uuid AND valid_until_exclusive IS NOT NULL));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000999',false);
SELECT lab.keep('unknown126_editorial',public.get_rtn_npa_editorial_workspace());
SELECT lab.check('250 editorial cannot approve incomplete126',(SELECT x->'latest_check'->'can_approve'='false'::jsonb FROM jsonb_array_elements(lab.ctx('unknown126_editorial')->'banks')x WHERE x->>'bank_id'=lab.ctx('bank_id')#>>'{}'));
SELECT lab.denied('250 actualapprove denies missing126 proof',$q$SELECT public.approve_rtn_npa_manifest((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_claim')->>'run_id')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,NULL,0,'Synthetic cannot approve partial126','86000000-0000-4000-8000-000000000127')$q$,'22023');
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',false);
SELECT lab.denied('250 normalstaff cannot configure omittedActualID',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic normalstaff cannot configure126',gen_random_uuid())$q$,'42501');
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000999',false);
SELECT lab.denied('250 presentdocid JSONnull rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":null}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid numericstring rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":"38355"}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid zero rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":0}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid negative rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":-1}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid fraction rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":1.5}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid boolean rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":true}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid object rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":{}}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid array rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":[]}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 presentdocid over13digits rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":10000000000000}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic malformed suppliedActualID',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 nonFederalLaw suppliednulldocid also rejected',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"kind":"Order","docid":null}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic anykind suppliedActualID invalid',gen_random_uuid())$q$,'22023');
SELECT lab.denied('250 FederalLaw number stays string evenwhen docid omitted',$q$SELECT public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"number":126}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic invalid numericlaw number',gen_random_uuid())$q$,'22023');
SELECT lab.keep('unknown126_maxID',public.configure_rtn_npa_basis((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('unknown126_configuration')->>'configuration_id')::uuid,(lab.ctx('fresh_release')->>'release_id')::uuid,jsonb_build_array(lab.ctx('unknown126_identity')||'{"docid":9999999999999}'::jsonb),(clock_timestamp()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic maximum structurallyvalidActualID',gen_random_uuid()));
SELECT lab.check('250 positive13digit upperbound declaredwithout automaticproof',lab.ctx('unknown126_maxID')->'supported_count'='1'::jsonb AND lab.ctx('unknown126_maxID')->'unsupported_count'='0'::jsonb);
SET ROLE postgres;
SELECT lab.check('250 declaration changes no oldkeyset',(SELECT to_jsonb(k)=lab.ctx('unknown126_before_key')FROM rtn_private.key_sets k WHERE k.id=(lab.ctx('fresh_review')->>'key_set_id')::uuid));
SELECT lab.check('250 declaration changes no oldattempt grade orsnapshot',(SELECT to_jsonb(t)=lab.ctx('old_attempt')FROM rtn_private.attempts t WHERE t.id=(lab.ctx('old_start')->>'attempt_id')::uuid));
SELECT lab.check('250 declaration changes no officialsource row',(SELECT to_jsonb(s)=lab.ctx('unknown126_before_source')FROM rtn_private.sources s WHERE s.id=(lab.ctx('source')->>'source_id')::uuid));
ROLLBACK TO SAVEPOINT unsupported_federal_law;
RELEASE SAVEPOINT unsupported_federal_law;
SET ROLE postgres;
SELECT lab.check('250 rollback retains original312 baseline configuration',(SELECT count(*)=1 AND min(id::text)=(lab.ctx('configuration')->>'configuration_id')FROM rtn_private.npa_configurations)AND NOT EXISTS(SELECT 1 FROM rtn_private.npa_check_runs));
